#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    static int count;
    string name;

    Cat(string n) : name(n) {
        count = count + 1;
    }

    static int howMany() {
        return count;
    }
};

int Cat::count = 0;

int main() {
    Cat a("{nameA}");
    Cat b("{nameB}");
    cout << "一共出生了 " << Cat::howMany() << " 只" << endl;
    cout << "第一只叫 " << a.name << endl;
    return 0;
}
